void *h = dlopen("libpack.so", RTLD_LAZY);   /* stage 1: load, symbols lazy */
if (!h) return fail(dlerror());
/* stage 2, per symbol, on first use: */
static part_fn *part;
if (!part) part = (part_fn *)dlsym(h, "pack_part");
if (!part) { dlclose(h); return fail(dlerror()); }
consume(part(...));
dlclose(h);                                  /* release the loaded object */
